<?php
namespace App\Services; use App\Repositories\RoleRepository; use Illuminate\Support\Facades\DB; use Spatie\Permission\Models\Role;
class RoleService { public function __construct(private RoleRepository $repo){} public function create(array $data):Role{return DB::transaction(function()use($data){$r=$this->repo->create($data);$r->syncPermissions($data['permissions']??[]);return $r;});} public function update(Role $role,array $data):Role{abort_if($role->name==='Super Admin',403,'Super Admin role is protected.'); return DB::transaction(function()use($role,$data){$r=$this->repo->update($role,$data);$r->syncPermissions($data['permissions']??[]);return $r;});} public function delete(Role $role):void{abort_if($role->name==='Super Admin',403,'Super Admin role is protected.'); abort_if($role->users()->exists(),422,'Role is assigned to users.');$this->repo->delete($role);} }
